schemas:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "ما أبرز مستلزمات الحضانة التي لا يمكن الاستغناء عنها في أي فصل؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "طاولات وكراسٍ بمقاس عمر الفصل، وحدة تخزين للحقائب، سبورة، ركن أدوات نشاط، وأرضية آمنة. هذه هي الحد الأدنى الذي يمر به الفصل التفتيش ويبدأ تشغيله."
      }
    },
    {
      "@type": "Question",
      "name": "كيف أتأكد من أن أثاث الحضانة يستوفي معايير السلامة المعتمدة للأطفال؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "اطلب من المورد شهادات المطابقة للمعايير الدولية مثل ISO 8124 للألعاب، وشهادات الطلاء الخالي من الرصاص والمواد السامة، ووثائق اختبار الثبات."
      }
    },

    {
      "@type": "Question",
      "name": "هل يختلف تجهيز روضة الأطفال عن تجهيز الحضانة من حيث المستلزمات؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "نعم في التفاصيل، لا في المبدأ. الروضة تخدم أعمارًا أكبر فتتغير مقاسات الأثاث وأنواع الألعاب، لكن منهجية التخطيط ومعايير السلامة وترتيب المناطق الوظيفية تبقى واحدة."
      }
    },
    {
      "@type": "Question",
      "name": "ما العوامل التي ترفع تكلفة تجهيز الحضانة أكثر من غيرها؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "جودة الخامات وبلد المنشأ يمثّلان الجزء الأكبر، تليهما شهادات السلامة الدولية ومدة الضمان، ثم اشتراطات التركيب وتوقيت الشراء بالنسبة لموسم بدء العام الدراسي."
      }
    },
    {
      "@type": "Question",
      "name": "كيف أوازن بين الجودة والتكلفة عند شراء مستلزمات الحضانة بكميات كبيرة؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "قسّم القائمة إلى بنود سلامة حرجة لا تفاوض فيها وبنود يمكن التوفير فيها بمواصفات أقل. طلب عرض موحّد على المجموع مع تفصيل واضح لكل بند يمنحك مساحة مساومة حقيقية."
      }
    },
    {
      "@type": "Question",
      "name": "ما الجهة الحكومية المصرية المسؤولة عن ترخيص الحضانات وتحديد متطلبات التجهيز؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ترخيص الحضانات في مصر يقع تحت مظلة وزارة التضامن الاجتماعي بمقتضى قانون الطفل ولائحته التنفيذية، مع اشتراطات صحية من وزارة الصحة واشتراطات دفاع مدني."
      }
    }
  ]
}
